function buildB3Patches(f: B3Family): [string, PracticalDecisionRuPatch][] {
  const distractors = { b1: B3_GENERIC.b1, b2: B3_GENERIC.b2 };
  const reasonDistractors = { br1: B3_GENERIC.br1, br2: B3_GENERIC.br2 };
  return [
    [`${f.prefix}-101`, {
      cueRu: f.baseRu,
      questionRu: B3_GENERIC.q1,
      explanationRu: f.whyRu,
      actionOptions: { good: f.signalRu, ...distractors },
      reasonOptions: { goodR: f.whyRu, ...reasonDistractors },
    }],
    [`${f.prefix}-102`, {
      cueRu: f.baseRu,
      questionRu: B3_GENERIC.q2,
      explanationRu: f.whyRu,
      actionOptions: { good: f.directRu, ...distractors },
      reasonOptions: { goodR: f.whyRu, ...reasonDistractors },
    }],
    [`${f.prefix}-103`, {
      cueRu: f.change1Ru,
      questionRu: B3_GENERIC.q3,
      explanationRu: f.whyRu,
      actionOptions: { good: B3_GENERIC.row3Good, ...distractors },
      reasonOptions: { goodR: f.whyRu, ...reasonDistractors },
    }],
    [`${f.prefix}-104`, {
      cueRu: f.change2Ru,
      questionRu: B3_GENERIC.q4,
      explanationRu: f.whyRu,
      actionOptions: { good: B3_GENERIC.row4Good, ...distractors },
      reasonOptions: { goodR: f.whyRu, ...reasonDistractors },
    }],
  ];
}

